from app import BookHandler
from urllib.parse import parse_qs

BookHandler.books = [{'id':1,'title':'1984','author':'George Orwell','isbn':'123','synopsis':'dystopian novel'}]

# Replicate do_GET_all logic
parsed_path = '/books'
qs = 'q=orwell'
filters = {}
for key, vals in parse_qs(qs).items():
    if len(vals) == 1:
        filters[key] = vals[0]

books = BookHandler.books[:]
if 'id' in filters:
    id_val = int(filters['id'])
    books = [b for b in BookHandler.books if b['id'] == id_val]
else:
    books = BookHandler.books[:]
for field, val in filters.items():
    if field == 'q':
        if not books:
            break
        books = [b for b in books if val in b[field].lower()]
    elif field in ['title', 'author', 'isbn', 'synopsis']:
        books = [b for b in books if val in b[field].lower()]

print('Books:', books)
